'use strict';
const games=[
 {title:'Blood Moon City',tag:'01 / THE HUNT',art:'☾',desc:'Feed, grow stronger, and survive a city that fights back.',intro:'You are the thing in the dark.',text:'Feed on wandering citizens to grow. Hunters appear as your notoriety rises. Survive the night or fall before dawn.',hint:'Move with WASD / arrow keys, or drag on the game. Feed by getting close to gold citizens. Space or P unleashes a pulse.'},
 {title:'The Last Sunset',tag:'02 / THE ESCAPE',art:'◐',desc:'Race between shadows before the last light finds you.',intro:'Stay in the shadows.',text:'The sun is rising and the safe shadows are shifting. Gather three moonstones and survive until dawn. Light burns.',hint:'Move with WASD / arrows or drag. Dark circles are safe; pale areas burn. Gather three blue moonstones and survive.'},
 {title:'Hunger Engine',tag:'03 / THE EVOLUTION',art:'✳',desc:'Your actions shape the monster you become.',intro:'Become what you hunt.',text:'Collect prey and survive. Moving evolves a swift Wraith; staying still creates a powerful Brute. Your form changes how you fight.',hint:'Move with WASD / arrows or drag. Your behavior shapes your evolution. Your attacks are automatic.'},
 {title:'Nocturne',tag:'04 / THE COMPOSITION',art:'♫',desc:'Survive the dark and make a song with your movement.',intro:'Play the night.',text:'Collect luminous notes to add layers to your song. Dodge the shadows while your movement shapes the music.',hint:'Move with WASD / arrows or drag. Collect notes to build the score. Enable sound above; audio begins after you start.'},
 {title:'The Midnight Court',tag:'05 / THE CONSPIRACY',art:'♜',desc:'Build influence, protect your secrecy, rule the night.',intro:'Power has a price.',text:'Guide your court through seven nights. Gain influence without letting suspicion reach 100, and keep your hunger under control.',hint:'Choose one action each night. Finish night seven with at least 40 influence, less than 100 suspicion, and hunger below 100.'}
];
const $=s=>document.querySelector(s),cards=$('#cards'),overlay=$('#overlay'),canvas=$('#canvas'),ctx=canvas.getContext('2d');let mode=0,state=null,last=0,keys={},pointer=null,sound=false,audio=null;
games.forEach((g,i)=>{let b=document.createElement('button');b.className=`card c${i+1}`;b.innerHTML=`<div class="card-top"><span>${g.tag}</span><span>↗</span></div><div class="card-art" aria-hidden="true">${g.art}</div><div class="card-content"><h3>${g.title}</h3><p>${g.desc}</p><span class="play">PLAY THE GAME &nbsp; →</span></div>`;b.addEventListener('click',()=>openGame(i));cards.appendChild(b)});
function openGame(i){mode=i;state=null;keys={};pointer=null;let g=games[i];$('#game-index').textContent=g.tag;$('#game-title').textContent=g.title;$('#intro-kicker').textContent='A GAME FOR THE NIGHT';$('#intro-title').textContent=g.intro;$('#intro-text').textContent=g.text;$('#start').textContent='BEGIN THE NIGHT →';$('#intro').classList.remove('hidden');$('#hint').textContent=g.hint;$('#hud').innerHTML='';$('#controls').innerHTML='';overlay.classList.remove('hidden');document.body.style.overflow='hidden';paintBackdrop();$('#close').focus()}
function closeGame(){overlay.classList.add('hidden');document.body.style.overflow='';state=null;keys={};pointer=null;cards.children[mode].focus()};$('#close').onclick=closeGame;document.addEventListener('keydown',e=>{if(!overlay.classList.contains('hidden')){if(e.key==='Escape'){closeGame();return}keys[e.key.toLowerCase()]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if((e.key===' '||e.key.toLowerCase()==='p')&&state&&mode===0)pulse()}});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
$('#sound').onclick=()=>{sound=!sound;$('#sound span').textContent=sound?' SOUND ON':' SOUND OFF';if(sound)initAudio()};function initAudio(){try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();audio.resume()}catch(e){sound=false}}function tone(freq,duration=.15,type='sine',vol=.05){if(!sound||!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}
function rand(a,b){return a+Math.random()*(b-a)}function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}function spawn(kind){return{x:rand(35,925),y:rand(35,505),kind,vx:rand(-1,1),vy:rand(-1,1),hp:kind==='hunter'?3:1}}
function start(){if(sound)initAudio();$('#intro').classList.add('hidden');$('#controls').innerHTML='';state={time:0,health:100,score:0,energy:100,player:{x:480,y:270},enemies:[],items:[],particles:[],spawn:0,form:'Awakening',moving:0,still:0,notes:0,lastNote:0,night:1,influence:15,suspicion:10,hunger:20,allies:0};if(mode===0){for(let i=0;i<10;i++)state.items.push(spawn('citizen'))}if(mode===1){for(let i=0;i<3;i++)state.items.push(spawn('stone'))}if(mode===2){for(let i=0;i<8;i++)state.items.push(spawn('prey'))}if(mode===3){for(let i=0;i<5;i++)state.items.push(spawn('note'))}if(mode===4)courtControls();else actionControls();last=performance.now();updateHud()}
$('#start').onclick=start;function actionControls(){let c=$('#controls');if(mode===0){let b=document.createElement('button');b.textContent='PULSE / SPACE';b.onclick=pulse;c.appendChild(b)}let p=document.createElement('span');p.className='mobile-pad';p.textContent='DRAG ON THE GAME TO MOVE';c.appendChild(p)}
function courtControls(){let actions=[['FEED','hunger −25 · suspicion +12',()=>{state.hunger-=25;state.suspicion+=12}],['RECRUIT','influence +10 · suspicion +9',()=>{state.influence+=10;state.suspicion+=9;state.allies++}],['LAY LOW','suspicion −18 · hunger +12',()=>{state.suspicion-=18;state.hunger+=12}],['SCHEME','influence +15 · hunger +10 · suspicion +12',()=>{state.influence+=15;state.hunger+=10;state.suspicion+=12}]];let c=$('#controls');actions.forEach(a=>{let b=document.createElement('button');b.innerHTML=`${a[0]}<br><small>${a[1]}</small>`;b.onclick=()=>{if(!state)return;a[2]();state.hunger=Math.max(0,state.hunger+5);state.suspicion=Math.max(0,state.suspicion);state.night++;tone(180+state.influence*3,.16);if(state.hunger>=100||state.suspicion>=100)end(false,'Your court has fallen.');else if(state.night>7)end(state.influence>=40,state.influence>=40?'The city belongs to your court.':'Your court survives, but lacks influence.');else updateHud()};c.appendChild(b)})}
function pulse(){if(!state||state.energy<35)return;state.energy-=35;state.enemies.forEach(e=>{if(dist(e,state.player)<145)e.hp-=3});state.particles.push({x:state.player.x,y:state.player.y,r:5,life:1});tone(110,.3,'sawtooth',.035)}
function end(win,title){if(!state)return;let score=mode===4?state.influence:Math.floor(state.score);let key='midnight-best-'+mode;let best=Math.max(score,Number(localStorage.getItem(key)||0));try{localStorage.setItem(key,best)}catch(e){}state=null;$('#intro-kicker').textContent=win?'THE NIGHT IS YOURS':'THE NIGHT REMEMBERS';$('#intro-title').textContent=title;$('#intro-text').textContent=`${mode===4?'Influence':'Score'}: ${score} · Best on this device: ${best}. Every night is another chance.`;$('#start').textContent='PLAY AGAIN →';$('#intro').classList.remove('hidden');$('#controls').innerHTML='';tone(win?440:110,.5,'sine')}
function updateHud(){if(!state)return;let s=state;if(mode===4){$('#hud').innerHTML=`<span>NIGHT <strong>${Math.min(s.night,7)} / 7</strong></span><span>INFLUENCE <strong>${s.influence}</strong></span><span>SUSPICION <strong>${s.suspicion}</strong></span><span>HUNGER <strong>${s.hunger}</strong></span><span>ALLIES <strong>${s.allies}</strong></span>`;return}let length=[75,60,75,60][mode];$('#hud').innerHTML=`<span>NIGHT <strong>${Math.max(0,Math.ceil(length-s.time))}s</strong></span><span>LIFE <strong>${Math.max(0,Math.ceil(s.health))}</strong></span><span>${mode===1?'MOONSTONES':mode===3?'NOTES':'POWER'} <strong>${Math.floor(s.score)}</strong></span>${mode===0?`<span>PULSE <strong>${Math.floor(s.energy)}%</strong></span>`:''}${mode===2?`<span>FORM <strong>${s.form}</strong></span>`:''}`}
function point(e){let r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*960/r.width,y:(e.clientY-r.top)*540/r.height}}canvas.addEventListener('pointerdown',e=>{pointer=point(e);canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(pointer)pointer=point(e)});canvas.addEventListener('pointerup',()=>pointer=null);canvas.addEventListener('pointercancel',()=>pointer=null);
function step(dt){let s=state;if(!s||mode===4)return;s.time+=dt;s.energy=Math.min(100,s.energy+dt*5);let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(pointer){let d=dist(pointer,s.player);if(d>8){dx=(pointer.x-s.player.x)/d;dy=(pointer.y-s.player.y)/d}}let moving=Math.hypot(dx,dy)>0;if(moving){let n=Math.hypot(dx,dy),speed=mode===2&&s.form==='Wraith'?235:180;s.player.x=Math.max(15,Math.min(945,s.player.x+dx/n*speed*dt));s.player.y=Math.max(15,Math.min(525,s.player.y+dy/n*speed*dt));s.moving+=dt}else s.still+=dt;if(mode===2&&s.time>12)s.form=s.moving>s.still?'Wraith':'Brute';
let interval=mode===0?Math.max(.45,2.4-s.score*.06):mode===2?1.1:mode===3?2.1:3;s.spawn+=dt;if(s.spawn>interval){s.spawn=0;let e=spawn('hunter');let side=Math.floor(rand(0,4));if(side===0)e.x=0;if(side===1)e.x=960;if(side===2)e.y=0;if(side===3)e.y=540;s.enemies.push(e)}
s.enemies.forEach(e=>{let d=dist(e,s.player)||1,sp=mode===1?55:mode===3?65:mode===2?65:75+s.score*.7;e.x+=(s.player.x-e.x)/d*sp*dt;e.y+=(s.player.y-e.y)/d*sp*dt;if(d<20)s.health-=dt*(mode===3?18:22)});
if(mode===2){s.lastNote+=dt;if(s.lastNote>.45){s.lastNote=0;let target=s.enemies.reduce((a,e)=>!a||dist(e,s.player)<dist(a,s.player)?e:a,null);if(target&&dist(target,s.player)<(s.form==='Brute'?190:145)){target.hp-=s.form==='Brute'?3:2;s.particles.push({x:target.x,y:target.y,r:4,life:.5});tone(160+Math.random()*140,.08)}}}
s.enemies=s.enemies.filter(e=>e.hp>0);s.items.forEach(item=>{if(item.kind==='citizen'||item.kind==='prey'){item.x=Math.max(12,Math.min(948,item.x+item.vx*20*dt));item.y=Math.max(12,Math.min(528,item.y+item.vy*20*dt))}if(dist(item,s.player)<22){item.dead=true;s.score++;s.health=Math.min(100,s.health+(mode===0?8:mode===2?4:0));if(mode===3){s.notes++;tone([220,261.63,293.66,329.63,392,440,523.25][s.notes%7],.5,'sine',.07)}else tone(350+s.score*10,.12);if(mode!==1)s.items.push(spawn(item.kind))}});s.items=s.items.filter(i=>!i.dead);
if(mode===1){let shadows=getShadows(s.time);let safe=shadows.some(sh=>dist(sh,s.player)<sh.r);if(!safe)s.health-=dt*9}
if(mode===3&&sound&&s.time-s.lastNote>.5){s.lastNote=s.time;tone([110,130.81,164.81,196][Math.floor(s.time*2)%4],.3,'triangle',.025)}s.particles.forEach(p=>{p.r+=dt*130;p.life-=dt*2});s.particles=s.particles.filter(p=>p.life>0);updateHud();let duration=[75,60,75,60][mode];if(s.health<=0)end(false,'The night claimed you.');else if(s.time>=duration){let win=mode!==1||s.score>=3;end(win,win?(mode===3?'Your song survives the dark.':'You survived until dawn.'):'You survived, but left moonstones behind.')}}
function getShadows(t){return[{x:150+t*4%780,y:160,r:100},{x:800-t*3%750,y:390,r:110},{x:490+Math.sin(t*.2)*90,y:270,r:75}]}
function paintBackdrop(){ctx.fillStyle='#181521';ctx.fillRect(0,0,960,540);ctx.fillStyle='#312535';for(let i=0;i<14;i++)ctx.fillRect((i*137)%960,(i*83)%540,75,55)}function circle(x,y,r,color){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()}function draw(){if(!state){paintBackdrop();return}let s=state;paintBackdrop();if(mode===4){ctx.fillStyle='#e8d8c5';ctx.font='38px Georgia';ctx.fillText('THE CITY IS LISTENING',80,120);ctx.fillStyle='#a596a5';ctx.font='20px sans-serif';ctx.fillText('One choice per night. Seven nights to build your court.',80,165);for(let i=0;i<7;i++){circle(120+i*115,300,32,i<s.night?'#d7f875':'#4e3a4e');ctx.fillStyle='#181521';ctx.font='bold 18px sans-serif';ctx.fillText(i+1,114+i*115,306)}return}if(mode===1){ctx.fillStyle='rgba(227,158,107,.28)';ctx.fillRect(0,0,960,540);getShadows(s.time).forEach(sh=>circle(sh.x,sh.y,sh.r,'#211d31'))}s.items.forEach(a=>{let col=a.kind==='stone'?'#96e4ee':a.kind==='note'?'#d7bcff':'#f3c78c';circle(a.x,a.y,9,col);circle(a.x,a.y,17,col+'22')});s.enemies.forEach(e=>{circle(e.x,e.y,13,'#db6876');circle(e.x,e.y,4,'#351a2c')});s.particles.forEach(p=>{ctx.strokeStyle=`rgba(216,248,117,${Math.max(0,p.life)})`;ctx.lineWidth=3;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.stroke()});circle(s.player.x,s.player.y,20,'#c5e87b22');circle(s.player.x,s.player.y,12,'#d8f875');circle(s.player.x+3,s.player.y-3,3,'#24212c');ctx.fillStyle='#f6f0e8';ctx.font='12px sans-serif';if(mode===1){ctx.fillText('SHADOWS MOVE — KEEP UP',24,30)}if(mode===2)ctx.fillText(s.form.toUpperCase()+' · YOUR ACTIONS SHAPE YOU',24,30);if(mode===3)ctx.fillText('COLLECT NOTES · BUILD THE MUSIC',24,30)}
function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;if(state&&!overlay.classList.contains('hidden')){step(dt);draw()}requestAnimationFrame(frame)}requestAnimationFrame(frame);
